import { assertDate, isLeapYear, toOrdinal, fromOrdinal, dayOfWeek } from './civil.mjs';

function assertYear(year) {
  if (!Number.isInteger(year) || year < 1 || year > 9999) throw new RangeError(`ano inválido: ${year}`);
