  assertYear(year);
  if (!Number.isInteger(week) || week < 1 || week > isoWeeksInYear(year)) throw new RangeError(`semana inválida: ${week}`);
  if (!Number.isInteger(weekday) || weekday < 1 || weekday > 7) throw new RangeError(`dia inválido: ${weekday}`);
