    case 'floor':
      out = q;
      break;
    case 'ceil':
      out = r === 0 ? q : q + 1;
      break;
    case 'trunc':
      out = r !== 0 && n < 0 ? q + 1 : q;
      break;
    case 'half-up':
      out = 2 * r > d || (2 * r === d && n >= 0) ? q + 1 : q;
      break;
    default:
      out = 2 * r > d || (2 * r === d && q % 2 !== 0) ? q + 1 : q;
  }
  return out === 0 ? 0 : out;
